const ExcelJS = require('exceljs');

async function applyOrangeHighlight() {
  const filePath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  const backupPath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명_backup_11847_12000.xlsx';

  console.log('Loading backup workbook...');
  const backupWb = new ExcelJS.Workbook();
  await backupWb.xlsx.readFile(backupPath);
  const backupSheet = backupWb.getWorksheet('기업 정보');

  console.log('Loading target workbook...');
  const targetWb = new ExcelJS.Workbook();
  await targetWb.xlsx.readFile(filePath);
  const targetSheet = targetWb.getWorksheet('기업 정보');

  const orangeFill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FFFFA500' } // Standard Orange
  };

  let modifiedCellsCount = 0;

  for (let r = 11847; r <= 12000; r++) {
    const origRow = backupSheet.getRow(r);
    const newRow = targetSheet.getRow(r);

    // Check columns 1 to 58
    for (let c = 1; c <= 58; c++) {
      const origVal = origRow.getCell(c).value;
      const newVal = newRow.getCell(c).value;

      const normOrig = origVal === null || origVal === undefined ? '' : String(origVal).trim();
      const normNew = newVal === null || newVal === undefined ? '' : String(newVal).trim();

      // If cell was modified or newly populated
      if (normNew !== '' && normNew !== normOrig) {
        newRow.getCell(c).fill = orangeFill;
        modifiedCellsCount++;
      }
    }
    newRow.commit();
  }

  console.log('Total modified/added cells highlighted in orange:', modifiedCellsCount);
  console.log('Saving target workbook...');
  await targetWb.xlsx.writeFile(filePath);
  console.log('Successfully saved target workbook with orange highlights!');
}

applyOrangeHighlight().catch(console.error);
